Given a matrix mat[][] of size n x n where every element is either 'O' or 'X', the task is to find the size of the largest square subgrid that is completely surrounded by 'X', i.e. the largest square where all its border cells are 'X'. Examples: Input: mat[][] = [ ['X', 'X'],                              ['X', 'X'] ]Output: 2Explanation: The largest square submatrix surrounded by 'X' is the whole  input matrix.Input: mat[][] = [ ['X', 'O', 'X', 'X', 'X'],                               ['X', 'X', 'X', 'X', 'X'],                               ['X', 'X', 'O', 'X', 'O'],                               ['X', 'X', 'X', 'X', 'X'],                               ['X', 'X', 'X', 'O', 'O'] ];    Output: 3Explanation: The square submatrix starting at (1, 1) is the largest submatrix surrounded by 'X'.Try It YourselfTable of ContentUsing Brute Force Method - O(n^4) Time and O(1) SpaceUsing DP and Prefix Sum - O(n^3) Time and O(n^2) SpaceUsing Brute Force Method - O(n^4) Time and O(1) SpaceThe idea is to iterate over each cell in the mat[][] and consider it as the top-left corner of potential square submatrices. For each starting cell, we’ll expand the square's size and check if the borders of that square consist entirely of 'X'. If they do, update the maximum size found. 
            C++

    #include <bits/stdc++.h>
using namespace std;

int largestSubsquare(vector<vector<char>>& mat) {
    int n = mat.size();
    int maxSize = 0;

    // Traverse each cell in the matrix
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {

            // For each cell (i, j), consider it as the
            // top-left corner of squares of increasing sizes
            for (int size = 1; size <= n - max(i, j); size++) {

                // Check if the square of 'size' with top-left
                // corner (i, j) has its borders as 'X'
                bool valid = true;

                // Check top and left side of the current square
                for (int k = 0; k < size; k++) {
                    if (mat[i][j + k] != 'X' || mat[i + k][j] != 'X') {
                        valid = false;
                        break;
                    }
                }

                // Check bottom and right sides of 
              	// the current square
                for (int k = 0; k < size; k++) {
                    if (mat[i + size - 1][j + k] != 'X' 
                        || mat[i + k][j + size - 1] != 'X') {
                        valid = false;
                        break;
                    }
                }

                // If the current square is valid,
                // update the maximum size found
                if (valid) {
                    maxSize = max(maxSize, size);
                }
            }
        }
    }

    return maxSize;
}

int main() {

    vector<vector<char>> mat =
              {{'X','X','X','O'},
               {'X','O','X','X'},
               {'X','X','X','O'},
               {'X','O','X','X'}};
    cout << largestSubsquare(mat);
}


